"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.11959",title:"MiMo-V2.6: Scaling Reinforcement Learning Towards Self-Improvement",up:74,href:"https://arxiv.org/abs/2610.11959",abstract:"Reinforcement learning (RL) is the central training paradigm for advancing large foundation models towards self-improvement. This report introduces the MiMo-V2.6 series, an omni-modal family that pushes the frontier of model intelligence by scaling RL compute. Prior to RL, we conduct mid-training on a broad multimodal corpus to provide ample exploration space, and build a solid infrastructure on the pretrained hybrid-SWA architecture to support subsequent scale-up. We scale RL compute along three dimensions: (1) larger batches and higher throughput, with an asynchronous training that consumes ",published:"2026-10-08T00:00:00Z"},{id:"2610.09087",title:"U-Space: Uncovering When and Why Uncertainty Arises in Language Models",up:40,href:"https://arxiv.org/abs/2610.09087",abstract:"Large language models are informing decisions with ever-higher stakes. As the consequences of their errors grow, a central question becomes harder to ignore: how much can we trust an individual answer? Yet recognizing when to defer remains difficult because language models can present incorrect conclusions with fluent explanations and an authoritative tone. Uncertainty quantification seeks to address this disconnect by estimating the reliability of individual predictions. However, many existing methods require repeated generations or separately trained components, and their scalar estimates do",published:"2026-10-06T00:00:00Z"},{id:"2610.11287",title:"REMORY: Learning Residual Memory for Context Compaction",up:38,href:"https://arxiv.org/abs/2610.11287",abstract:"Long-horizon agents compact their history to continue within a finite context window, but a textual summary alone may not support every subsequent decision. We introduce REMORY, a neural memory network that supplements the summary with a bounded sequence of soft memory tokens. Given the history and summary, the network learns to generate tokens that help a frozen LLM approximate the continuation it would produce with the full history. The tokens are conditioned on the summary and appended after it, forming an analogue of a residual connection along the sequence dimension. On SummHay, REMORY im",published:"2026-10-08T00:00:00Z"},{id:"2610.12421",title:"Beyond Spatio-Temporal Priors: A Generalizable Approach for Dense Correspondence Matching",up:38,href:"https://arxiv.org/abs/2610.12421",abstract:"Dense correspondence matching has historically been bounded by simplifying spatio-temporal priors, such as smooth motion and rigid geometry. While effective for classical tasks, these assumptions break down in image editing and reference-guided generation (IEG), where transformations can preserve visual identity while breaking physical continuity. To establish identity-preserving correspondence across such transformations, we introduce FreeMatching, a generalizable framework combining generative and semantic foundation representations with heterogeneous supervision from classical datasets, tra",published:"2026-10-08T00:00:00Z"},{id:"2610.11794",title:"Memento 3: Model-Based Recursive Self-Improvement through Reflective Rulebooks",up:35,href:"https://arxiv.org/abs/2610.11794",abstract:"Learning to act in unfamiliar environments requires agents to infer how the world works and revise that understanding as new evidence arrives. Yet limited observations can support multiple world models that explain past interactions but predict different outcomes in unseen states. We introduce Memento 3, building on the Memento series to enable frozen LLM agents to continually learn explicit world models through external memory. The agent maintains a natural-language rulebook as persistent semantic memory, recording revisable hypotheses about environment dynamics while leaving unknown aspects ",published:"2026-10-08T00:00:00Z"},{id:"2610.13395",title:"ProgramGym: Scaling Training Environments for Long-Horizon Program Reproduction Agents",up:20,href:"https://arxiv.org/abs/2610.13395",abstract:"Coding agents are increasingly used to build programs from scratch as software engineers do rather than to resolve issues within a repository or to generate a repository from a given requirements document. However, scalable verifiable training environments that force agents to discover what is required and to decide how the system should be designed remain scarce. Moreover, existing agent workflows also cannot sustain long-horizon development in which the agent explores the reference program before implementation. To address these challenges, we introduce ProgramGym, a framework consisting of ",published:"2026-10-09T00:00:00Z"},{id:"2610.07121",title:"SoloQ: Calibration-Free Quantization for Diffusion Language Models",up:19,href:"https://arxiv.org/abs/2610.07121",abstract:"Diffusion large language models dLLMs) have emerged as a promising alternative to autoregressive language models through bidirectional diffusion-based token generation. However, their growing model sizes and high inference costs make efficient deployment challenging: full-sequence denoising repeatedly invokes compute-intensive forward passes, while block-diffusion models additionally introduce a memory-intensive KV-cache. Low-bit weight-activation quantization is therefore attractive, yet existing dLLM post-training quantization methods rely on calibration data despite activation distributions",published:"2026-10-05T00:00:00Z"},{id:"2610.12423",title:"Pumpire: Unified Benchmark for Metric Distance Estimation",up:18,href:"https://arxiv.org/abs/2610.12423",abstract:"We present Pumpire, a unified benchmark for evaluating metric point-pair distance estimation capability of both image- and video-level 3D foundation models, with or without depth priors. In contrast to previous approaches that normally evaluate depth and camera intrinsics separately or evaluate point-clouds with geometric similarity metrics, which cannot directly reflect models' point-to-point distance estimation capability, Pumpire directly assesses point-to-point distances from the reconstructed geometry. To this end, we collect a large-scale and diverse dataset (pumpire-6k) comprising 100 r",published:"2026-10-08T00:00:00Z"},{id:"2609.33987",title:"Opera: A Verbal Critic Framework for Long-horizon Coding Agents",up:14,href:"https://arxiv.org/abs/2609.33987",abstract:"Long-horizon coding agents need timely corrections, yet feedback can be ineffective or even harmful when it misjudges ongoing work or fails to address the underlying problem. Existing critics focus on evaluating trajectories and generating feedback, but rarely track what happens after feedback is delivered. We present Opera, a verbal critic framework that treats each correction as a persistent note, followed until the diagnosed problem is resolved. Opera decides when to review through periodic and event-driven triggers, diagnoses issues with typed operators, audits feedback against visible evi",published:"2026-10-08T00:00:00Z"},{id:"2609.38748",title:"Here the World in Stereo: Learning Dynamic Spatial Correspondence for Immersive Joint Video-Audio Generation",up:14,href:"https://arxiv.org/abs/2609.38748",abstract:"Recent joint video-audio generation models have achieved strong semantic correspondence and temporal synchronization. However, applications such as AR/VR and interactive gaming further require stereo audio to provide an immersive sense, which remains largely overlooked. Effective stereo audio requires the perceived sound location to evolve consistently with the motion of its corresponding visual source. We refer to this property as Dynamic Spatial Correspondence and propose StereoBind, a framework that binds visual source motion to stereo sound generation. StereoBind uses motion tracks to coor",published:"2026-09-30T00:00:00Z"},{id:"2606.03335",title:"A GPU-Parallel Framework for Heterogeneous Multi-Task Reinforcement Learning",up:12,href:"https://arxiv.org/abs/2606.03335",abstract:"GPU-parallel simulation provides abundant robot interaction, but existing benchmarks rarely combine this scale with heterogeneous manipulation tasks and standardized multi-task RL evaluation. We introduce Hebero (Heterogeneous Benchmark for Robot Learning), a GPU-parallel Isaac Lab benchmark that enables efficient joint training and evaluation of a single policy across all 40 heterogeneous tasks. Scaling experiments show that increasing parallel replicas per task improves success under a fixed wall-clock budget. To support learning with sparse rewards and limited demonstrations, we propose Dem",published:"2026-10-06T00:00:00Z"},{id:"2610.13912",title:"RSI-Anything: Unlocking Recursive Self-Improvement with World Models",up:11,href:"https://arxiv.org/abs/2610.13912",abstract:"Recursive self-improvement (RSI) aims to transform interaction experience into persistent improvements, yet external feedback is costly and world-model predictions may become unreliable as policies evolve. We introduce RSI-Anything, a domain-general framework built on JEPA-Anything that uses predictive world models to guide action and learning-data selection. Observed feedback drives policy or workflow improvement and conditional world-model adaptation, while component and compatibility checks govern the retention of updated policy-model pairs. Across diverse computational and scientific domai",published:"2026-10-09T00:00:00Z"},{id:"2609.35855",title:"Mara Chain: Rethinking Failure as a Stepping Stone for AI System Auto-Evolution",up:9,href:"https://arxiv.org/abs/2609.35855",abstract:"Optimizing deployed AI systems increasingly amounts to editing prompts, skills, harnesses, and code rather than model weights. Existing approaches commonly optimize these artifacts through propose-evaluate-select procedures, where candidate configurations are evaluated and only those meeting an acceptance criterion are selected. Yet our analysis shows that discarded candidates often contain information critical for subsequent optimization. Discarding them causes later proposals to revisit the same failure modes. We introduce Mara Chain, a refinement procedure that turns rejected candidates int",published:"2026-09-25T00:00:00Z"},{id:"2609.37712",title:"PolyOCR-Venus: Unified OCR Foundation Models for Text-Centric Visual Intelligence",up:8,href:"https://arxiv.org/abs/2609.37712",abstract:"Optical Character Recognition (OCR) is evolving from plain-text transcription toward general visual intelligence, requiring models to recognize, localize, and reason over textual information in complex visual environments. However, existing OCR systems often excel at only some tasks and struggle to balance recognition, parsing, and reasoning across scenarios. In this report, we present PolyOCR, a family of unified OCR foundation models of varying scales. PolyOCR combines a shared instruction-following framework with a large-scale data engine that converts heterogeneous visual resources into qu",published:"2026-09-29T00:00:00Z"},{id:"2610.08927",title:"Can AI Agents Make Open-Ended Scientific Discovery? Evidence from Station",up:8,href:"https://arxiv.org/abs/2610.08927",abstract:"Recent AI systems have made rapid progress in scientific discovery when given well-defined metrics, but whether they can autonomously undertake open-ended scientific discovery remains unclear. We investigate AI's ability to tackle open-ended tasks in Station, an open-world environment in which multiple agents simulate a scientific ecosystem. To tackle challenges specific to open-ended tasks, we propose augmenting Station with two mechanisms: a Supervisor mechanism and periodic Meta Reflection, which encourage persistent exploration even when intermediate metrics are lacking. We construct open-",published:"2026-10-06T00:00:00Z"},{id:"2610.10355",title:"MIRA: A Musical Intent Refinement Agent for Aligning Text-to-Music Generation with User Intent",up:8,href:"https://arxiv.org/abs/2610.10355",abstract:"Text-to-music systems produce increasingly convincing audio, yet evaluation reveals little about whether the result matches user intent. A global text-audio relevance score can overlook the implicit intent in underspecified prompts and mask failures in specific requirements, such as instrumentation, structure, rhythm, or mood progression. To bridge this gap, we formulate text-to-music intent alignment as satisfying a per-request rubric of independently verifiable items covering both a request's explicit requirements and its implied musical intent. Scoring items individually makes evaluation di",published:"2026-10-07T00:00:00Z"},{id:"2610.12183",title:"A Closer Look at Agentic BBO: Benchmarking LLM Agents for Black-Box Optimization",up:8,href:"https://arxiv.org/abs/2610.12183",abstract:"Black-box optimization (BBO) arises in many scientific and engineering problems where objective evaluations are expensive and limited. Recent large language model (LLM) agents offer a new way to approach BBO by combining task semantics, computation, optimization tools, and feedback-driven decision making, showing great potential due to the integration with mathematically rigorous tools. However, existing agentic BBO studies use different task domains and system configurations, making their results difficult to compare and the effects of individual design choices hard to isolate. We therefore i",published:"2026-10-08T00:00:00Z"},{id:"2610.12399",title:"SpaceFlow: Locally Controllable 3D Generation",up:8,href:"https://arxiv.org/abs/2610.12399",abstract:"Current 3D generation methods lack explicit local control: geometric adherence is often defined by a global control strength, and appearance cannot be specified locally. We present SpaceFlow, a training-free pipeline for locally controllable 3D generation from text descriptions and a collection of geometric primitives. Each primitive serves as a proxy for an object part and is assigned a local control level, enabling users to specify whether regions should strictly follow the input shape or allow generative completion. During structure generation, we enforce these spatial constraints within th",published:"2026-10-08T00:00:00Z"},{id:"2610.12459",title:"WorldGuide: Goal-Directed Video World Model for Procedural Task Execution",up:8,href:"https://arxiv.org/abs/2610.12459",abstract:"Video generators and video-based world models can synthesize plausible visual trajectories, but long-horizon procedural tasks require generation to adapt to what has actually been produced. A model must determine the next action from its generated state, execute that action, and recognize when the task is complete. Open-loop generation cannot adapt to execution outcomes, while existing closed-loop systems often rely on pretrained executors or indirect verification. This leaves a gap between deciding an action and successfully realizing it. We formulate procedural video generation as closed-loo",published:"2026-10-08T00:00:00Z"},{id:"2610.04875",title:"SpecFold: Folding Multi-Branch Redundancy for Faster Speculative Decoding in Diffusion Language Models",up:7,href:"https://arxiv.org/abs/2610.04875",abstract:"Diffusion large language models (DLLMs) generate text through iterative block denoising, and multi-branch speculative decoding accelerates this process by verifying a main branch together with multiple draft branches in a single forward pass. While prior DLLM acceleration methods primarily exploit temporal redundancy across denoising steps, we identify a complementary redundancy axis within each speculative verification step: multi-branch computational redundancy. During speculative verification, draft branches inherit most tokens from their parents while unmasking a small set of additional po",published:"2026-10-06T00:00:00Z"},{id:"2610.08917",title:"CARE: Certifying Acceleration for Vision-Language-Action Inference",up:7,href:"https://arxiv.org/abs/2610.08917",abstract:"While vision-language-action (VLA) models have advanced rapidly, running them at every control step remains expensive. Prior work accelerates VLA inference using techniques like action chunking and visual-token pruning, typically evaluating based on latency and average task success. However, acceleration may discard information and break tasks the original policy would solve, a risk hidden by average metrics. Measuring these failures is challenging because action deviations compound over closed-loop trajectories, meaning task failure is only observable across full episodes. We therefore define",published:"2026-10-06T00:00:00Z"},{id:"2610.10549",title:"Synthesis Through Simulation: Generating Coherent Enterprise Data via Scalable Agent-System Interaction",up:7,href:"https://arxiv.org/abs/2610.10549",abstract:"Tool-calling agents have become central to enterprise AI, yet training and evaluating them at scale remains severely constrained due to business and legal restrictions on enterprise systems, data, and database schemas. Tabular data synthesis offers a natural alternative, but its effectiveness is fundamentally limited by structural validity and schema availability, while procedure-based approaches yield the opposite weakness, typically lacking distributional fidelity without per-domain authoring. We introduce **Synthesis Through Simulation** (STS), a **schema--free** data synthesis paradigm in ",published:"2026-09-24T00:00:00Z"},{id:"2610.11566",title:"Incremental Open-Ended Deep Research with Structured Harness",up:7,href:"https://arxiv.org/abs/2610.11566",abstract:"Existing Open-Ended Deep Research (OEDR) systems primarily generate reports from scratch, making them inefficient for scenarios where research reports need to be continuously maintained as new information emerges. We introduce Incremental Open-Ended Deep Research (Incremental-OEDR), a research setting that treats a report as an evolving research state and incrementally updates it by preserving valid knowledge, revising outdated or incomplete content, and incorporating newly available information. To support this setting, we propose Structured Harness, which represents reports as structured col",published:"2026-10-08T00:00:00Z"},{id:"2610.12448",title:"One Block, Multiple Depths: Recurrent Vision Transformers with Depth-Programmed Experts",up:7,href:"https://arxiv.org/abs/2610.12448",abstract:"In this work, we show that a single Transformer block, applied recurrently, can match the accuracy of a full-depth vision encoder at comparable inference FLOPs without intermediate feature distillation. reViT restores depth-specific transformations by representing the FFN at each recurrent depth as a convex combination of a small shared expert bank. A continuous normalized-depth coordinate programs this mixture, defining a resampleable trajectory through FFN parameter space. We evaluate this design in two regimes: supervised ImageNet-1k training and distillation from a DINOv2 teacher. Across b",published:"2026-10-08T00:00:00Z"},{id:"W7171516088",title:"SpecBox: Speculative Sandbox Scheduling for Efficient LLM Agent Serving",up:0,href:"https://doi.org/10.48550/arxiv.2607.23933",crossrefDoi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7171516088",crossrefIssued:"2026-08-24"},{id:"W7204032694",title:"Do Not Let Sandboxes Sit Idle: Cross-Agent Sandbox Re-allocation for LLM Agents",up:0,href:"https://doi.org/10.1007/978-981-92-4805-6_13",doi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7204032694"},{id:"W4416036585",title:"Can LLMs Help You at Work? A Sandbox for Evaluating LLM Agents in Enterprise Environments",up:0,href:"https://doi.org/10.18653/v1/2025.emnlp-main.466",doi:"https://doi.org/10.18653/v1/2025.emnlp-main.466",year:2025,openalexId:"https://openalex.org/W4416036585"}]}}]);